cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <c10/cuda/CUDAStream.h>
#include <c10/cuda/CUDAException.h>
#include <cute/tensor.hpp>
#include <mma.h>
using namespace cute;
namespace wmma = nvcuda::wmma;

__global__ void cute_conv2d_kernel(
    const __nv_bfloat16* __restrict__ input,
    const __nv_bfloat16* __restrict__ weight,
    __nv_bfloat16* __restrict__ output,
    int N,
    int H,
    int W,
    int Ho,
    int Wo)
{
    constexpr int TILE_H = 8;
    constexpr int TILE_W = 16;
    constexpr int TILE_M = TILE_H * TILE_W;
    constexpr int TILE_N = 32;
    constexpr int KERNEL_K = 3 * 3 * 3;
    constexpr int MMA_K = 32;
    constexpr int THREADS = 512;
    constexpr int SMEM_W = TILE_W + 2;
    constexpr int SMEM_H = TILE_H + 2;

    __shared__ __nv_bfloat16 smem_input[SMEM_H * SMEM_W * 3];
    __shared__ __nv_bfloat16 smem_a[TILE_M * MMA_K];
    __shared__ __nv_bfloat16 smem_b[MMA_K * TILE_N];
    __shared__ float smem_output[TILE_M * TILE_N];

    const int tid = threadIdx.x;
    const int tile_x = blockIdx.x * TILE_W;
    const int tile_y = blockIdx.y * TILE_H;
    const int batch = blockIdx.z;

    for (int linear = tid; linear < SMEM_H * SMEM_W * 3; linear += THREADS) {
        const int ic = linear % 3;
        const int t = linear / 3;
        const int ix = t % SMEM_W;
        const int iy = t / SMEM_W;
        const int gx = tile_x + ix;
        const int gy = tile_y + iy;
        if (gx < W && gy < H) {
            smem_input[(iy * SMEM_W + ix) * 3 + ic] =
                input[((batch * 3 + ic) * H + gy) * W + gx];
        } else {
            smem_input[(iy * SMEM_W + ix) * 3 + ic] =
                __float2bfloat16(0.0f);
        }
    }
    __syncthreads();

    for (int linear = tid; linear < TILE_M * MMA_K; linear += THREADS) {
        const int m = linear / MMA_K;
        const int k = linear % MMA_K;
        if (k < KERNEL_K) {
            const int ky = (k / 3) % 3;
            const int kx = k % 3;
            const int ic = k / 9;
            const int iy = m / TILE_W;
            const int ix = m % TILE_W;
            smem_a[m * MMA_K + k] =
                smem_input[((iy + ky) * SMEM_W + (ix + kx)) * 3 + ic];
        } else {
            smem_a[m * MMA_K + k] = __float2bfloat16(0.0f);
        }
    }

    for (int linear = tid; linear < MMA_K * TILE_N; linear += THREADS) {
        const int k = linear / TILE_N;
        const int n = linear % TILE_N;
        if (k < KERNEL_K) {
            smem_b[k * TILE_N + n] = weight[n * KERNEL_K + k];
        } else {
            smem_b[k * TILE_N + n] = __float2bfloat16(0.0f);
        }
    }
    __syncthreads();

    const int warp_id = tid >> 5;
    const int warp_m = (warp_id >> 1) * 16;
    const int warp_n = (warp_id & 1) * 16;

    wmma::fragment<wmma::accumulator, 16, 16, 16, float> acc;
    wmma::fill_fragment(acc, 0.0f);

    wmma::fragment<wmma::matrix_a, 16, 16, 16, __nv_bfloat16, wmma::row_major> a_frag;
    wmma::fragment<wmma::matrix_b, 16, 16, 16, __nv_bfloat16, wmma::row_major> b_frag;

    wmma::load_matrix_sync(a_frag, smem_a + warp_m * MMA_K, MMA_K);
    wmma::load_matrix_sync(b_frag, smem_b + warp_n, TILE_N);
    wmma::mma_sync(acc, a_frag, b_frag, acc);

    wmma::load_matrix_sync(a_frag, smem_a + warp_m * MMA_K + 16, MMA_K);
    wmma::load_matrix_sync(b_frag, smem_b + 16 * TILE_N + warp_n, TILE_N);
    wmma::mma_sync(acc, a_frag, b_frag, acc);

    wmma::store_matrix_sync(
        smem_output + warp_m * TILE_N + warp_n,
        acc,
        TILE_N,
        wmma::mem_row_major);
    __syncthreads();

    for (int linear = tid; linear < TILE_M * TILE_N; linear += THREADS) {
        const int m = linear / TILE_N;
        const int n = linear % TILE_N;
        const int oy = tile_y + m / TILE_W;
        const int ox = tile_x + m % TILE_W;
        if (oy < Ho && ox < Wo) {
            const int out_idx =
                ((batch * 32 + n) * Ho + oy) * Wo + ox;
            output[out_idx] = __float2bfloat16(smem_output[linear]);
        }
    }
}


torch::Tensor cute_conv2d(
    torch::Tensor input,
    torch::Tensor weight)
{
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(input.scalar_type() == at::kBFloat16, "input must be bfloat16");
    TORCH_CHECK(weight.scalar_type() == at::kBFloat16, "weight must be bfloat16");
    TORCH_CHECK(input.device() == weight.device(), "input and weight must be on the same CUDA device");
    TORCH_CHECK(input.dim() == 4, "input must be NCHW");
    TORCH_CHECK(weight.sizes() == torch::IntArrayRef({32, 3, 3, 3}),
                "weight must have shape [32, 3, 3, 3]");

    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();
    TORCH_CHECK(input_c.is_contiguous(),
                "input conversion failed");
    TORCH_CHECK(weight_c.is_contiguous(),
                "weight conversion failed");

    const int N = static_cast<int>(input_c.size(0));
    const int C = static_cast<int>(input_c.size(1));
    const int H = static_cast<int>(input_c.size(2));
    const int W = static_cast<int>(input_c.size(3));
    TORCH_CHECK(N > 0, "empty batch is not supported");

    TORCH_CHECK(C == 3, "input must have 3 channels");
    TORCH_CHECK(H >= 3 && W >= 3, "input spatial dimensions must be at least 3");

    const int Ho = H - 2;
    const int Wo = W - 2;
    TORCH_CHECK(Ho > 0 && Wo > 0, "empty output is not supported");

    auto output = torch::empty(
        {N, 32, Ho, Wo},
        input_c.options());

    dim3 block(512);
    dim3 grid(
        (Wo + 15) / 16,
        (Ho + 7) / 8,
        N);
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_conv2d_kernel<<<grid, block, 0, stream>>>(
        reinterpret_cast<const __nv_bfloat16*>(
            input_c.data_ptr<at::BFloat16>()),
        reinterpret_cast<const __nv_bfloat16*>(
            weight_c.data_ptr<at::BFloat16>()),
        reinterpret_cast<__nv_bfloat16*>(
            output.data_ptr<at::BFloat16>()),
        N, H, W, Ho, Wo);

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
